    21  LIBICAL_VCARD_EXPORT struct vcardparameter_impl *vcardparameter_new_impl(vcardparameter_kind kind)
    22  {
    23      struct vcardparameter_impl *v;
    24
    25      if ((v = (struct vcardparameter_impl *)icalmemory_new_buffer(sizeof(struct vcardparameter_impl))) == 0) {
    26          icalerror_set_errno(ICAL_NEWFAILED_ERROR);
    27          return 0;
    28      }
    29
    30      memset(v, 0, sizeof(struct vcardparameter_impl));
    31
    32      strcpy(v->id, "para");
    33
    34      v->kind = kind;
    35      v->value_kind = vcardparameter_kind_value_kind(kind, &v->is_multivalued);
    36
    37      return v;
    38  }
