   297  bool vcardparameter_isa_parameter(void *parameter)
   298  {
   299      const struct vcardparameter_impl *impl = (struct vcardparameter_impl *)parameter;
   300
   301      if (parameter == 0) {
   302          return false;
   303      }
   304
   305      if (strcmp(impl->id, "para") == 0) {
   306          return true;
   307      } else {
   308          return false;
   309      }
